  T extends Array<
      UseSuspenseQueryOptions<
        infer TQueryFnData,
        infer TError,
        infer TData,
        infer TQueryKey
      >
    >
  ? Array<UseSuspenseQueryOptions<TQueryFnData, TError, TData, TQueryKey>>
  : // Fallback
    Array<UseSuspenseQueryOptions>

/**
 * SuspenseQueriesResults reducer recursively maps type param to results
 */
export type SuspenseQueriesResults<
  T extends Array<any>,
  TResult extends Array<any> = [],
  TDepth extends ReadonlyArray<number> = [],
> = TDepth['length'] extends MAXIMUM_DEPTH
  ? Array<UseSuspenseQueryResult>
  : T extends []
  ? []
  : T extends [infer Head]
  ? [...TResult, GetSuspenseResults<Head>]
  : T extends [infer Head, ...infer Tail]
  ? SuspenseQueriesResults<
      [...Tail],
      [...TResult, GetSuspenseResults<Head>],
      [...TDepth, 1]
    >
  : T extends Array<
      UseSuspenseQueryOptions<
        infer TQueryFnData,
        infer TError,
        infer TData,
        any
      >
    >
  ? // Dynamic-size (homogenous) UseQueryOptions array: map directly to array of results
    Array<
      UseSuspenseQueryResult<
        unknown extends TData ? TQueryFnData : TData,
        TError
      >
    >
  : // Fallback
    Array<UseSuspenseQueryResult>

export function useSuspenseQueries<T extends any[]>({
  queries,
  context,
}: {
  queries: readonly [...SuspenseQueriesOptions<T>]
  context?: UseQueryOptions['context']
}): SuspenseQueriesResults<T> {
  return useQueries({
    queries: queries.map((query) => ({
      ...query,
      enabled: true,
      useErrorBoundary: true,
      suspense: true,
      placeholderData: undefined,
      networkMode: 'always' as NetworkMode,
    })),
    context,
  }) as SuspenseQueriesResults<T>
}
